public static class AccessPages
{
    public static string Users() => """
<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>Kullanıcılar & Yetkiler | İnokskar</title><link rel="stylesheet" href="/r104-access.css?v=r14-9"><link rel="stylesheet" href="/r123-professional.css"><script src="/r123-security.js" defer></script><link rel="stylesheet" href="/r13-interface.css?v=r22-clean"><link rel="stylesheet" href="/r13-pages.css?v=r22-clean"><script src="/r13-pages.js?v=r22-clean" defer></script></head><body><header class="access-top private-brand-header"><a class="private-brand-link" href="/" aria-label="İNOKSKAR ana sayfa"><img class="private-brand-image" src="/inokskar-header-brand.png" alt="İNOKSKAR Soğutma ve Endüstriyel Mutfak"></a><nav><a href="/admin">← Yönetim paneli</a><a href="/teknik">Teknik Servis</a></nav></header><main class="access-wrap"><section class="access-heading"><div><p class="eyebrow">ERİŞİM YÖNETİMİ</p><h1>Admin ve teknik servis hesapları</h1><p>Her kullanıcı kendi e-posta/şifresiyle giriş yapar. Yetkiler sunucu tarafında uygulanır; yalnız arayüzde gizlenmekle kalmaz.</p></div><div class="access-actions"><button type="button" id="add-admin" class="button">+ Admin ekle</button><button type="button" id="add-tech" class="button secondary">+ Teknik servis ekle</button></div></section><div id="access-notice"></div><section class="access-card"><div class="access-toolbar"><input id="access-search" type="search" placeholder="Ad, e-posta veya rol ara"><div class="role-filter"><button type="button" class="filter active" data-role="all">Tümü</button><button type="button" class="filter" data-role="Admin">Adminler</button><button type="button" class="filter" data-role="TechnicalService">Teknik Servis</button><button type="button" class="filter" data-role="inactive">Pasif</button></div></div><div id="access-list"></div></section></main><dialog id="access-dialog"><form id="access-form" method="dialog"><div class="dialog-head"><div><p class="eyebrow">KULLANICI HESABI</p><h2 id="access-form-title">Kullanıcı ekle</h2></div><button type="button" class="icon-btn" id="access-close" aria-label="Kapat">×</button></div><input type="hidden" name="id"><div class="two"><label>Ad Soyad<input name="name" maxlength="100" required></label><label>Rol<select name="role"><option value="Admin">Admin</option><option value="TechnicalService">Teknik Servis</option></select></label></div><label>E-posta<input name="email" type="email" maxlength="180" required autocomplete="off"></label><label id="password-row">İlk Şifre<input name="password" type="password" minlength="8" maxlength="128" autocomplete="new-password"><small>Yeni kullanıcı ilk girişte bu şifreyle giriş yapar.</small></label><label class="switch"><input name="active" type="checkbox" checked><span>Hesap aktif</span></label><label class="switch" id="must-change-row"><input name="mustChangePassword" type="checkbox" checked><span>İlk girişten sonra şifre değişikliği iste</span></label><section class="permission-section"><div><h3>Yetkiler</h3><p>“Müdahale” seçildiğinde görüntüleme otomatik açılır. Teknik dosyalarda indirme ayrı yetkidir.</p></div><div class="permission-table"><div class="permission-head"><strong>Modül</strong><strong>Görüntüle</strong><strong>Müdahale</strong><strong>İndir</strong></div><div id="permission-rows"></div></div></section><div class="dialog-actions"><button type="button" class="button secondary" id="access-cancel">Vazgeç</button><button type="submit" class="button">Kaydet</button></div></form></dialog><dialog id="password-dialog"><form id="password-form" method="dialog"><div class="dialog-head"><h2>Şifreyi sıfırla</h2><button type="button" class="icon-btn" id="password-close">×</button></div><input type="hidden" name="id"><label>Yeni geçici şifre<input name="password" type="password" minlength="8" maxlength="128" required autocomplete="new-password"></label><label class="switch"><input name="mustChangePassword" type="checkbox" checked><span>Sonraki girişte şifre değişikliği iste</span></label><div class="dialog-actions"><button type="button" class="button secondary" id="password-cancel">Vazgeç</button><button type="submit" class="button">Şifreyi güncelle</button></div></form></dialog><script src="/r104-access.js?v=r14-9" defer></script></body></html>
""";

    public static string AccountSecurity(string email, string role) => """
<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>Hesap Güvenliği | İnokskar</title><link rel="stylesheet" href="/r104-access.css?v=r14-9"><link rel="stylesheet" href="/r123-professional.css"><script src="/r123-security.js" defer></script><link rel="stylesheet" href="/r13-interface.css?v=r22-clean"><link rel="stylesheet" href="/r13-pages.css?v=r22-clean"><script src="/r13-pages.js?v=r22-clean" defer></script></head><body><header class="access-top private-brand-header"><a class="private-brand-link" href="/" aria-label="İNOKSKAR ana sayfa"><img class="private-brand-image" src="/inokskar-header-brand.png" alt="İNOKSKAR Soğutma ve Endüstriyel Mutfak"></a><nav>@@ACCOUNT_NAV@@</nav></header><main class="access-wrap narrow"><section class="access-card"><p class="eyebrow">HESABIM</p><h1>Şifre değiştir</h1><p><strong>@@EMAIL@@</strong> · @@ROLE@@</p><form id="own-password" class="password-form"><label>Mevcut şifre<input name="currentPassword" type="password" required autocomplete="current-password"></label><label>Yeni şifre<input name="newPassword" type="password" minlength="8" maxlength="128" required autocomplete="new-password"></label><label>Yeni şifre tekrar<input name="confirmPassword" type="password" minlength="8" maxlength="128" required autocomplete="new-password"></label><button class="button">Şifreyi değiştir</button><p id="own-password-note"></p></form></section></main><script>document.getElementById('own-password').addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget,n=document.getElementById('own-password-note');const b={currentPassword:f.currentPassword.value,newPassword:f.newPassword.value,confirmPassword:f.confirmPassword.value};if(b.newPassword!==b.confirmPassword){n.textContent='Yeni şifreler aynı değil.';return;}const r=await fetch('/api/account/password',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(b)});const j=await r.json().catch(()=>({}));if(!r.ok){n.textContent=j.error||'Şifre değiştirilemedi.';return;}location.href='/login?reset=1';});</script></body></html>
""".Replace("@@EMAIL@@", System.Net.WebUtility.HtmlEncode(email), StringComparison.Ordinal).Replace("@@ROLE@@", System.Net.WebUtility.HtmlEncode(role), StringComparison.Ordinal).Replace("@@ACCOUNT_NAV@@", role=="Customer"?"<a href='/hesabim/profil'>← Hesabıma dön</a><a href='/'>Siteye dön</a>":"<a href='/admin'>Yönetim</a><a href='/teknik'>Teknik Servis</a>", StringComparison.Ordinal);
}
